    val vector: ImageVector by lazy {
        ImageVector.Builder(name = key, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
            .addPath(pathData = addPathNodes(fill), fill = SolidColor(Color.Black))
            .apply {
                strokes.forEach {
                    addPath(
                        pathData = addPathNodes(it),
                        stroke = SolidColor(Color.Black),
                        strokeLineWidth = strokeWidth,
                        strokeLineCap = StrokeCap.Round,
                        strokeLineJoin = StrokeJoin.Round,
                    )
                }
            }
            .build()
    }

    companion object {
        /** The icon stored under [key], or null for no icon or a key this version doesn't know. */
        fun fromKey(key: String?): EventIcon? = key?.let { k -> entries.firstOrNull { it.key == k } }
    }
